-- ============================================
-- LUMA — Thème 7 : 3e scénario COURT x4 — Retourner un article défectueux
-- ============================================


update scenarios set content = '{"characters": {"clerk": "le vendeur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "clerk", "text": "Hi, how can I help you today?", "text_fr": "Bonjour, comment puis-je vous aider aujourd''hui ?", "choices": [{"text": "I bought this blender last week, and it stopped working already.", "text_fr": "J''ai acheté ce mixeur la semaine dernière, et il a déjà arrêté de fonctionner.", "next": "n2"}, {"text": "I''d like to return this, it''s broken and I have the receipt.", "text_fr": "J''aimerais retourner ça, c''est cassé et j''ai le reçu.", "next": "n2b"}]}, "n2": {"speaker": "clerk", "text": "I''m sorry to hear that. Do you have the receipt with you?", "text_fr": "Je suis désolé d''entendre ça. Vous avez le reçu avec vous ?", "choices": [{"text": "Yes, right here.", "text_fr": "Oui, juste ici.", "next": "n3"}, {"text": "I don''t have the paper one, but I have the email confirmation.", "text_fr": "Je n''ai pas le papier, mais j''ai l''email de confirmation.", "next": "n3b"}]}, "n2b": {"speaker": "clerk", "text": "Perfect, let''s take a look at it.", "text_fr": "Parfait, jetons un coup d''œil.", "choices": [{"text": "Here it is — it just stopped turning on yesterday.", "text_fr": "Le voici — il a juste arrêté de s''allumer hier.", "next": "n3"}]}, "n3": {"speaker": "clerk", "text": "Thank you. Would you prefer a refund or an exchange for the same item?", "text_fr": "Merci. Vous préférez un remboursement ou un échange pour le même article ?", "choices": [{"text": "I''d like a refund, please.", "text_fr": "J''aimerais un remboursement, s''il vous plaît.", "next": "n4"}, {"text": "An exchange would be great, I still need a blender.", "text_fr": "Un échange serait super, j''ai encore besoin d''un mixeur.", "next": "n4b"}]}, "n3b": {"speaker": "clerk", "text": "That works too, let me pull it up in our system.", "text_fr": "Ça marche aussi, laissez-moi le trouver dans notre système.", "choices": [{"text": "Thank you, I appreciate the flexibility.", "text_fr": "Merci, j''apprécie la flexibilité.", "next": "n4"}]}, "n4": {"speaker": "clerk", "text": "No problem, I''ll process the refund to your original payment method.", "text_fr": "Aucun problème, je vais traiter le remboursement sur votre moyen de paiement d''origine.", "choices": [{"text": "Thank you, how long will that take to show up?", "text_fr": "Merci, combien de temps ça prendra pour apparaître ?", "next": "n5"}]}, "n4b": {"speaker": "clerk", "text": "Great, let me grab a new one from the back for you.", "text_fr": "Super, laissez-moi en chercher un nouveau en réserve pour vous.", "choices": [{"text": "Thank you, I appreciate it.", "text_fr": "Merci, j''apprécie.", "next": "n5"}]}, "n5": {"speaker": "clerk", "text": "Usually 3 to 5 business days for a refund, or right away for the exchange.", "text_fr": "Généralement 3 à 5 jours ouvrables pour un remboursement, ou tout de suite pour l''échange.", "choices": [{"text": "That works for me, thank you for your help.", "text_fr": "Ça me va, merci pour votre aide.", "next": "n6"}]}, "n6": {"speaker": "clerk", "text": "Of course, sorry again for the inconvenience with the original one.", "text_fr": "Bien sûr, encore désolé pour le désagrément avec l''original.", "choices": [{"text": "No worries, these things happen. Thanks for handling it smoothly.", "text_fr": "Pas de souci, ça arrive. Merci de l''avoir géré sans problème.", "next": "end_resolved"}]}, "end_resolved": {"speaker": "clerk", "text": "Have a great day, and let us know if you need anything else!", "text_fr": "Bonne journée, et faites-nous savoir si vous avez besoin d''autre chose !", "end": true, "ending_label": "Retour géré sans problème 🔄✅"}}}'::jsonb, is_playable = true
where title = 'Retourner un article défectueux'
  and theme_id = (select id from scenario_themes where position = 7 and language_id = (select id from languages where code = 'en'));
